package net.officefloor.hq.app.setting;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

public class SaveFloor {
    public void save(@Val Floor floor, @Val Sheet sheet, SettingRepository repository) {
        if (floor.value() != null) {
            repository.saveDated(sheet.id(), DatedSettings.FLOOR, DatedSettings.fromOr(floor.from(), sheet.today()),
                    floor.value().toPlainString());
        }
    }
}
package net.officefloor.hq.app.setting;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

public class SaveRounding {
    public void save(@Val RoundingSetting rounding, @Val Sheet sheet, SettingRepository repository) {
        if (rounding.given()) {
            repository.saveDated(sheet.id(), DatedSettings.ROUNDING,
                    DatedSettings.fromOr(rounding.from(), sheet.today()), rounding.value());
        }
    }
}
